{
  "window_id": "w0033",
  "observed_failures": [
    {
      "receipt": "034.jpg",
      "field": "date",
      "symptom": "Predicted 2018-08-09 while image shows '09/03/2018'. OCR likely misread the month digit and the first plausible DD/MM/YYYY match was accepted without any cross-check against other date-like tokens on the receipt.",
      "field_feedback": "date_correct=false, amount_correct=true"
    },
    {
      "receipt": "074.jpg",
      "field": "total_amount",
      "symptom": "Predicted 702.00 while receipt shows 'Total Amt Rounded 102.00'. OCR mangled the final 'Total Amt Rounded' label to 'Toial Amt Rounded' (no word-boundary TOTAL hit) and wrote '102.00' as '702.00' on the 'Total incl. of GST' line; the skill's tier-4 search locked onto that corrupted-but-labeled line.",
      "field_feedback": "date_correct=true, amount_correct=false"
    },
    {
      "receipt": "077.jpg",
      "field": "total_amount",
      "symptom": "Predicted 23.26 (the 'Total (Inclusive of GST)' line) while the final 'TOTAL: 23.25' line (post rounding adjustment -0.01) is the intended value. 'Last match within tier' did not reach the standalone 'TOTAL:' line that follows a rounding adjustment row.",
      "field_feedback": "date_correct=true, amount_correct=false"
    },
    {
      "receipt": "078.jpg",
      "field": "total_amount",
      "symptom": "Cell contains empty string '' instead of either 92.80 or a real null. Receipt shows 'Total: 92.80' and 'Grand Total: 92.80'. The GRAND TOTAL priority regex (\\bGRAND\\s+TOTAL\\b) also would not match a concatenated 'GrandTotal' token, and when extraction fell through the skill wrote '' instead of None.",
      "field_feedback": "date_correct=true, amount_correct=false"
    },
    {
      "receipt": "ALL",
      "field": "process",
      "symptom": "Source run hit max_iterations (65) with stop_reason=max_iterations and acp_stop_reason=max_turn_requests; verifier binary reward was 0.0 despite 0.909 field accuracy. Agent spent many iterations hand-tuning regexes case-by-case rather than consolidating a reusable extraction pattern via the Skill.",
      "field_feedback": "n/a"
    }
  ],
  "root_causes": [
    {
      "id": "RC1",
      "description": "Priority keyword patterns in the original image-ocr skill (and in the agent's ad-hoc regexes) are whitespace-strict. OCR routinely collapses, splits, or substitutes the separator between 'GRAND' and 'TOTAL', between 'TOTAL' and 'RM', and between 'NET'/'NETT' and 'TOTAL'. Strict \\s+ misses concatenated or punctuated variants ('GrandTotal', 'GRANDTOTAL:', 'TOTAL:RM', 'TOTAL/RM').",
      "evidence": "078.jpg 'GrandTotal' not picked up; agent trace shows manual regex authoring with \\bGRAND\\s+TOTAL\\b."
    },
    {
      "id": "RC2",
      "description": "Within a tier, 'last candidate line' is the only tie-break and there is no preference for lines whose label semantically indicates the post-rounding/final total ('ROUND', 'ROUNDED', 'AFTER ROUNDING', 'NET', 'FINAL', 'GRAND'). On receipts where a 'Total (Inclusive ...)' line is followed by a 'Rounding Adj' and then a standalone 'TOTAL: X' line, the standalone line may fail to re-match if OCR broke the label, and the earlier pre-rounding value wins.",
      "evidence": "077.jpg predicted 23.26 instead of 23.25."
    },
    {
      "id": "RC3",
      "description": "Numeric-token extraction accepts the first digit sequence Tesseract emits without a second pass or sanity check. A single OCR hallucination (1→7, 0→9, 2→7) in the digits on the chosen keyword line propagates directly to the output. No digit-whitelist re-OCR of the specific line and no cross-check against adjacent 'Payment', 'Cash', or item-subtotal numbers is performed.",
      "evidence": "074.jpg '702.00' vs '102.00'; 034.jpg '09/08' vs '09/03'."
    },
    {
      "id": "RC4",
      "description": "Extraction-failure-to-cell mapping is not null-safe. On failure the writer emitted '' instead of a Python None, so the Excel cell is a string of length 0 rather than an empty cell. The xlsx strict-schema contract requires real nulls; this both fails graders and masks the failure as 'present but blank' in dashboards.",
      "evidence": "078.jpg total_amount is '' in the delivered xlsx; task prompt explicitly says 'If extraction fails ... the value is set to null'."
    },
    {
      "id": "RC5",
      "description": "The source agent spent 65 iterations hand-authoring regexes for individual receipts rather than invoking the image-ocr skill as a reusable pipeline. n_skill_invocations=0 and the run was terminated at max_iterations. The current skill set does not make 'invoke image-ocr' the obvious cheapest path for structured receipt extraction, so the agent re-derives the pipeline from scratch and runs out of budget before converging."
    }
  ],
  "skill_defects": [
    {
      "skill": "image-ocr",
      "defect": "Structured-field extraction patterns are too literal. GRAND TOTAL / TOTAL RM / NET TOTAL patterns require explicit whitespace; they do not tolerate OCR-concatenated labels ('GrandTotal'), punctuation-joined labels ('TOTAL:RM', 'TOTAL/RM'), or '-' separators. The 'two-line fallback' only looks one line down and does not look one line up for right-aligned label/value splits."
    },
    {
      "skill": "image-ocr",
      "defect": "No rule for 'final-after-rounding' selection. When multiple TOTAL-tier candidates exist on the same receipt, the skill picks the last match but does not prefer lines whose label contains ROUND/ROUNDED/AFTER ROUNDING/NET/FINAL/GRAND, and does not re-scan the next 1–2 lines after a 'Rounding Adj' line for a bare 'TOTAL: X' value."
    },
    {
      "skill": "image-ocr",
      "defect": "No targeted re-OCR of the chosen numeric token. When a candidate line is selected, the skill does not run a second Tesseract pass on the cropped line/number region with --psm 7 and a numeric whitelist, nor does it cross-check the extracted amount against sibling amounts on the receipt (CASH, PAYMENT, item subtotal). Single-pass digit errors (1↔7, 0↔9, 8↔3, 5↔6) go uncorrected."
    },
    {
      "skill": "image-ocr",
      "defect": "Date extraction lacks confidence gating and cross-validation. Only the first plausible pattern match is returned; there is no second pass on a line crop, no sanity check against other date tokens on the same receipt, and no guard against DD/MM vs MM/DD ambiguity (defaults to DD/MM silently). 2-digit years are assumed to be 20YY without an explicit upper bound tied to the receipt corpus."
    },
    {
      "skill": "image-ocr",
      "defect": "Failure semantics are under-specified. The skill says 'return None' on failure in prose but does not codify a single `process_receipt(path) -> dict` return shape that the caller MUST pass through to the writer, so callers end up substituting '' or NaN in Excel cells."
    },
    {
      "skill": "xlsx",
      "defect": "Strict-Schema section correctly says 'use Python None for nulls' but does not show the mandatory last-mile transform. It needs an explicit step: after building the DataFrame, replace '', 'None', 'NaN', pd.NA with Python None for every null-eligible column, cast the column to object dtype, and then re-read the file and assert that failed cells are None (not '')."
    },
    {
      "skill": "xlsx",
      "defect": "Strict-Schema checklist does not surface the specific check that would have caught 078: after write, iterate over null-eligible columns and raise if any non-null entry is an empty string or the literal 'None'/'NaN'."
    },
    {
      "skill": "openai-vision",
      "defect": "The skill is available but never cross-referenced from image-ocr as an escalation path for digit/date disambiguation when Tesseract confidence is low on a receipt line. For receipts whose keyword line has low per-word confidence, a targeted vision re-read of the amount/date token is a cheap recovery."
    },
    {
      "skill": "pdf",
      "defect": "No cross-reference from image-ocr: when source inputs include scanned receipts delivered inside a PDF (common sibling task), the skill does not direct callers to pdf→image rasterization before OCR, so a near-identical task starting from PDF would require re-deriving the pipeline."
    },
    {
      "skill": "video-frame-extraction",
      "defect": "Not directly implicated, but lacks a cross-reference back to image-ocr for the common 'extract frames then OCR text overlays' pipeline, so the agent would not discover the receipt-extraction primitives through this skill either."
    }
  ],
  "repair_recommendations": [
    {
      "target_skill": "image-ocr",
      "change": "In the 'Structured Field Extraction' section, replace the strict \\s+ keyword patterns with separator-tolerant forms: GRAND[\\s_\\-]*TOTAL, TOTAL[\\s:\\-]*RM, TOTAL[\\s_\\-]*AMOUNT, NETT?[\\s_\\-]*TOTAL, (TOTAL|AMOUNT)[\\s_\\-]*DUE. Explicitly document that OCR commonly concatenates or substitutes separators and that tier matching must tolerate '', ' ', ':', '-', '_', '/' between the words."
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a 'Final-After-Rounding Preference' subsection: when a priority tier has >1 candidate line, prefer lines whose label contains any of ROUND, ROUNDED, AFTER\\s*ROUNDING, NET, FINAL, GRAND; otherwise prefer the candidate that is followed by CASH / PAYMENT / CHANGE / TENDERED within the next 3 lines; otherwise fall back to the current 'last candidate' rule. Also: after any line matching ROUNDING\\s*ADJ, scan the next 2 non-empty lines for a bare 'TOTAL\\b[^A-Za-z]*<number>' and prefer that value."
    },
    {
      "target_skill": "image-ocr",
      "change": "Add a 'Digit-Safe Re-OCR' subsection. For the chosen total line and the chosen date line, crop the line's bounding box from pytesseract.image_to_data output and re-OCR with config '--psm 7 -c tessedit_char_whitelist=0123456789.,:/-'. Accept the value only if (a) the full-page OCR and the re-OCR agree on the digit sequence, or (b) the re-OCR value also appears elsewhere on the receipt (e.g., on a CASH/PAYMENT line). If neither holds, emit None rather than guessing."
    },
    {
      "target_skill": "image-ocr",
      "change": "Expand the 'Date Extraction and ISO Normalization' subsection: run date regex on both the full-page OCR and a line-cropped --psm 7 re-OCR of any line containing 'DATE' or 'TIME'; prefer dates that appear in both. For ambiguous DD/MM vs MM/DD, consult other date-like tokens on the same receipt; if still ambiguous, follow a documented default (DD/MM for this corpus) and emit a warning rather than silently committing. For 2-digit years, require that the resulting 4-digit year be within the receipt's plausible range (document a configurable window)."
    },
    {
      "target_skill": "image-ocr",
      "change": "Codify the return contract. Add a boxed section: 'process_receipt(path) MUST return {\"date\": str|None, \"total_amount\": str|None} where str is already in the final ISO/2-decimal shape and None is Python None (never \"\", \"None\", or NaN). Callers MUST pass the dict through to the Excel writer without further coercion.'"
    },
    {
      "target_skill": "image-ocr",
      "change": "Cross-reference the openai-vision skill as an optional escalation: 'If the chosen keyword line's average Tesseract per-word confidence (from image_to_data) is below 60, call openai-vision on the cropped line with a prompt that asks only for the labeled numeric/date value, and prefer that result when it agrees with at least one Tesseract pass.' Keep this optional to avoid cost blow-up."
    },
    {
      "target_skill": "xlsx",
      "change": "In the 'Strict-Schema Outputs' section, add a mandatory null-sanitization step with code: for every column that may contain nulls, run df[col] = df[col].where(df[col].notna() & (df[col] != '') & (df[col] != 'None') & (df[col] != 'NaN'), None) and df[col] = df[col].astype(object) before to_excel. Then in the verification block, explicitly assert that for every row, failed cells are Python None (type(cell) is type(None)) and not a zero-length string."
    },
    {
      "target_skill": "xlsx",
      "change": "Extend the 'Pitfalls That Break Line-by-Line Grading' list with a new item: 'Writing empty string for a failed extraction instead of a real null. Verifiers that compare on cell value or cell type will treat \"\" and None as different.' Include a one-line snippet showing the openpyxl read-back check: cell.value is None."
    },
    {
      "target_skill": "openai-vision",
      "change": "Add a short 'Line-level Field Rescue for OCR' subsection that documents a minimal prompt pattern ('Return ONLY the labeled value after \"TOTAL\" as a JSON object {\"total\": \"...\"} or {\"total\": null}') and advises using detail=high on a tightly cropped line image. Cross-reference image-ocr as the primary extractor and openai-vision as the fallback."
    },
    {
      "target_skill": "pdf",
      "change": "Add a one-paragraph cross-reference under 'Extract Text from Scanned PDFs' pointing at image-ocr's Structured Field Extraction patterns for receipt-style scanned PDFs, so that a near-identical task starting from PDF reuses the same tier/exclusion/null-safe pipeline rather than re-deriving it."
    },
    {
      "target_skill": "video-frame-extraction",
      "change": "Add a short 'Downstream OCR of extracted frames' note that links to image-ocr for text overlays and receipt-like frames, keeping the skill set internally consistent and reducing the chance that the agent re-derives extraction logic in a video-adjacent task."
    }
  ],
  "confidence": {
    "overall": 0.72,
    "notes": "High confidence on RC1/RC4 (reproducible from the predicted cells and the observed regex style). Medium confidence on RC2/RC3 — the exact OCR text and per-receipt tier decisions were inferred from the diagnostic trace; the specific line selection for 077/074 may depend on OCR variance across runs. RC5 is supported by execution metadata (max_iterations termination, n_skill_invocations=0). Recommendations are scoped to edits of the five existing SKILL.md files and avoid prescribing oracle values."
  }
}
